<?php
$id = isset($_GET['id']) ? (string) $_GET['id'] : 'TW-BATTLE-000001';
if (!preg_match('/^TW-BATTLE-[0-9]{6}$/', $id)) { http_response_code(400); exit('Invalid battle ID.'); }
$file = __DIR__ . '/battles-public/' . $id . '.json';
if (!is_file($file)) { http_response_code(404); exit('Battle not found.'); }
$battle = json_decode((string) file_get_contents($file), true);
if (!is_array($battle)) { http_response_code(500); exit('Battle record is invalid.'); }
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function side_name($battle,$side){ return $side === 'a' ? ($battle['participant_a_name'] ?? 'Participant A') : ($battle['participant_b_name'] ?? 'Participant B'); }
function score_total($scores){ return array_sum(array_map('intval', $scores ?: [])); }
?>
